import json, subprocess
d=json.load(open('/tmp/sf-publish/inventory.json'))
pkgs=[p for p in d['packages'] if p['state']=='changed']
def bump(v,kind):
    x,y,z=map(int,v.split('.'))
    return f"{x}.{y+1}.0" if kind=='minor' else f"{x}.{y}.{z+1}"
plan={}
for p in pkgs:
    base=p.get('baselineGitHead')
    out=subprocess.run(['git','log','--format=%s','%s..origin/dev'%base,'--',p['path']],capture_output=True,text=True).stdout.strip().split('\n')
    feats=[o for o in out if o and o.lower().startswith('feat')]
    kind='minor' if feats else 'patch'
    plan[p['name']]={'path':p['path'],'from':p['baselineVersion'],'to':bump(p['baselineVersion'],kind),'kind':kind}
# topological rounds
names=set(plan); edges={n:[] for n in names}
for n,info in plan.items():
    m=json.loads(subprocess.run(['git','show',f"origin/dev:{info['path']}/package.json"],capture_output=True,text=True).stdout)
    for sec in ('dependencies','peerDependencies','optionalDependencies'):
        for k in (m.get(sec) or {}):
            if k in names and k!=n: edges[n].append(k)
rounds=[]; remaining=dict(edges)
while remaining:
    ready=sorted([n for n,ds in remaining.items() if not any(dd in remaining for dd in ds)])
    rounds.append(ready)
    for n in ready: del remaining[n]
json.dump({'plan':plan,'rounds':rounds},open('/tmp/sf-publish/plan.json','w'),indent=1)
for i,r in enumerate(rounds,1): print(f"Round {i} ({len(r)}): {', '.join(sorted(r))}")
print()
mn=[(k,v) for k,v in sorted(plan.items()) if v['kind']=='minor']
print(f"MINOR ({len(mn)}):"); [print(f"  {k}: {v['from']} -> {v['to']}") for k,v in mn]
print(f"PATCH ({len(plan)-len(mn)})")
EOF

